class _ButaneFlutterApiCodec extends StandardMessageCodec {
  const _ButaneFlutterApiCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is AdvertisementData) {
      buffer.putUint8(128);
      writeValue(buffer, value.encode());
    } else if (value is CharacteristicData) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    } else if (value is CharacteristicProperty) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    } else if (value is DescriptorData) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    } else if (value is PeripheralData) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    } else if (value is PeripheralSessionIdentifier) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is ScanData) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is ServiceData) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 128: 
        return AdvertisementData.decode(readValue(buffer)!);
      case 129: 
        return CharacteristicData.decode(readValue(buffer)!);
      case 130: 
        return CharacteristicProperty.decode(readValue(buffer)!);
      case 131: 
        return DescriptorData.decode(readValue(buffer)!);
      case 132: 
        return PeripheralData.decode(readValue(buffer)!);
      case 133: 
        return PeripheralSessionIdentifier.decode(readValue(buffer)!);
      case 134: 
        return ScanData.decode(readValue(buffer)!);
      case 135: 
        return ServiceData.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

